#include <assert.h>
long sum_array(const long *a, long n);
int main(void) {
    long a[] = {1, 2, 3, -4};
    assert(sum_array(a, 4) == 2);
    assert(sum_array(a, 0) == 0);
    return 0;
}

#include <assert.h>
unsigned long my_strlen(const char *s);
int main(void) {
    assert(my_strlen("hello") == 5);
    assert(my_strlen("") == 0);
    return 0;
}

#include <assert.h>
long max3(long a, long b, long c);
int main(void) {
    assert(max3(1, 2, 3) == 3);
    assert(max3(-1, -5, -3) == -1);
    assert(max3(7, 7, 2) == 7);
    return 0;
}

#include <assert.h>
#include <string.h>
void to_upper(char *s);
int main(void) {
    char a[] = "Hello, World! z{";
    to_upper(a);
    assert(strcmp(a, "HELLO, WORLD! Z{") == 0);
    char b[] = "";
    to_upper(b);
    assert(b[0] == 0);
    return 0;
}

#include <assert.h>
unsigned long gcd(unsigned long a, unsigned long b);
int main(void) {
    assert(gcd(12, 18) == 6);
    assert(gcd(0, 5) == 5);
    assert(gcd(7, 0) == 7);
    assert(gcd(17, 13) == 1);
    return 0;
}
